
fn argument<T: serde::de::DeserializeOwned>(params: &serde_json::Value, key: &str) -> Result<T> {
    serde_json::from_value(params.get(key).cloned().unwrap_or(serde_json::Value::Null))
        .map_err(|_| Error::new("InvalidArgument", "ipc", format!("Invalid or missing argument: {key}")))
}
fn encode<T: Serialize>(value:T) -> Result<serde_json::Value> {
    serde_json::to_value(value).map_err(|_| Error::new("SerializationError","ipc","Could not encode response"))
}
async fn dispatch(state: &AppState, method: &str, params: serde_json::Value) -> Result<serde_json::Value> {
    if state.startup_smoke&&matches!(method,"manage_service"|"install_client_update"){return Err(Error::new("VerificationOnly","verification","Обслуживание системы отключено в проверочном сеансе."));}
    if state.runtime_preparing.load(std::sync::atomic::Ordering::Acquire)&&blocked_during_runtime_change(method){return Err(Error::new("RuntimePreparing","runtime-operation","Дождитесь завершения проверки или обновления ядер."));}
    match method {
        "check_client_update" => encode(check_client_update().await?),
        "download_client_update" => encode(download_client_update(host::State(state), argument(&params,"release")?).await?),
        "install_client_update" => encode(install_client_update(host::State(state), argument(&params,"release")?).await?),
        "bootstrap" => encode(bootstrap(host::State(state)).await?),
        "connect" => encode(connect(host::State(state), argument::<String>(&params, "id")?).await?),
        "disconnect" => encode(disconnect(host::State(state)).await?),
        "log_days" => encode(log_days(host::State(state)).await?),
        "log_read" => encode(log_read(host::State(state), argument::<String>(&params, "day")?, argument::<String>(&params, "category")?).await?),
        "profile_transport" => encode(profile_transport(host::State(state), argument::<String>(&params, "id")?).await?),
        "save_profile_transport" => encode(save_profile_transport(host::State(state), argument::<String>(&params, "id")?, argument::<Option<netpulse_core::transport_options::ProfileTransport>>(&params, "value")?).await?),
        "profile_json" => encode(profile_json(host::State(state), argument::<String>(&params, "id")?).await?),
        "save_profile_json" => encode(save_profile_json(host::State(state), argument::<String>(&params, "id")?, argument::<String>(&params, "json")?).await?),
        "playground_processes" => encode(playground_processes(host::State(state)).await?),
        "connection_analysis" => encode(connection_analysis(host::State(state), argument::<Option<u32>>(&params, "pid")?, argument::<String>(&params, "path")?).await?),
        "snapshot" => encode(snapshot(host::State(state)).await?),
        "import_text" => encode(import_text(host::State(state), argument::<String>(&params, "text")?).await?),
        "import_clipboard" => encode(import_clipboard(host::State(state)).await?),
        "copy_proxy_endpoint" => encode(copy_proxy_endpoint(host::State(state)).await?),
        "copy_log_text" => encode(copy_log_text(argument::<String>(&params, "text")?)?),
        "copy_event" => encode(copy_event(host::State(state), argument::<String>(&params, "id")?).await?),
        "copy_ip" => encode(copy_ip(argument::<String>(&params, "ip")?)?),
        "import_file" => encode(import_file(host::State(state), argument::<bool>(&params, "qr")?).await?),
        "delete_profile" => encode(delete_profile(host::State(state), argument::<String>(&params, "id")?).await?),
        "add_subscription" => encode(add_subscription(host::State(state), argument::<String>(&params, "name")?, argument::<String>(&params, "url")?, argument::<Option<bool>>(&params, "protected")?).await?),
        "copy_subscription_url" => encode(copy_subscription_url(host::State(state), argument::<String>(&params, "id")?).await?),
        "save_subscription" => encode(save_subscription(host::State(state), argument::<String>(&params, "id")?, argument::<String>(&params, "name")?, argument::<u32>(&params, "interval_hours")?, argument::<bool>(&params, "protected")?, argument::<Option<bool>>(&params, "lock_configuration")?).await?),
        "import_routing" => encode(import_routing().await?),
        "export_routing" => encode(export_routing(argument::<netpulse_core::routing::RoutingSettings>(&params, "routing")?).await?),
        "update_subscription" => encode(update_subscription(host::State(state), argument::<String>(&params, "id")?).await?),
        "delete_subscription" => encode(delete_subscription(host::State(state), argument::<String>(&params, "id")?).await?),
        "save_preferences" => encode(save_preferences(host::State(state), argument::<Preferences>(&params, "preferences")?).await?),
        "quick_network" => encode(quick_network(host::State(state), argument::<Option<bool>>(&params, "tun")?, argument::<Option<bool>>(&params, "system_proxy")?, argument::<Option<netpulse_core::model::RouteMode>>(&params, "route_mode")?, argument::<Option<String>>(&params, "transport_engine")?).await?),
        "quick_ui" => encode(quick_ui(host::State(state), argument::<UiPatch>(&params, "patch")?).await?),
        "active_latency" => encode(active_latency(host::State(state), argument::<String>(&params, "id")?).await?),
        "check_core_updates" => encode(check_core_updates().await?),
        "list_core_releases" => encode(list_core_releases(argument::<String>(&params, "engine")?).await?),
        "update_core" => encode(update_core(host::State(state), argument::<netpulse_core::core_releases::Release>(&params, "release")?).await?),
        "open_core_page" => encode(open_core_page(argument::<String>(&params, "url")?)?),
        "activate_core_bundle" => encode(activate_core_bundle(host::AppHandle, host::State(state), argument::<bool>(&params, "rollback")?).await?),
        "quit_application" => encode(quit_application(host::AppHandle, host::State(state)).await?),
        "start_latency" => encode(start_latency(host::State(state), argument::<Vec<String>>(&params, "ids")?, argument::<String>(&params, "method")?).await?),
        "start_speed" => encode(start_speed(host::State(state), argument::<netpulse_core::diagnostics::SpeedRequest>(&params, "request")?).await?),
        "current_diagnostic" => encode(current_diagnostic(host::State(state)).await?),
        "diagnostic_status" => encode(diagnostic_status(host::State(state), argument::<String>(&params, "id")?).await?),
        "cancel_diagnostic" => encode(cancel_diagnostic(host::State(state), argument::<String>(&params, "id")?).await?),
        "diagnostic_history" => encode(diagnostic_history(host::State(state), argument::<String>(&params, "kind")?).await?),
        "select_profile" => encode(select_profile(host::State(state), argument::<String>(&params, "id")?).await?),
        "install_compatibility_runtime" => encode(install_compatibility_runtime(host::State(state)).await?),
        "manage_service" => encode(manage_service(host::AppHandle, host::State(state), argument::<bool>(&params, "install")?, argument::<Option<bool>>(&params, "upgrade")?, argument::<Option<bool>>(&params, "repair")?).await?),
        "read_application_catalog" => encode(read_application_catalog(host::State(state)).await?),
        "save_application_catalog" => encode(save_application_catalog(host::State(state), argument::<Vec<inventory::Application>>(&params, "applications")?).await?),
        "scan_applications" => encode(scan_applications().await?),
        "application_icon" => encode(application_icon(argument::<String>(&params, "path")?).await?),
        "choose_exe" => encode(choose_exe().await?),
        "public_ip" => encode(public_ip(host::State(state)).await?),
        "public_ips" => encode(public_ips(host::State(state)).await?),
        "install_engine" => encode(install_engine(host::State(state)).await?),
        "clear_logs" => encode(clear_logs(host::State(state)).await?),
        "clear_file_logs" => encode(clear_file_logs(host::State(state)).await?),
        "logs" => encode(logs(host::State(state)).await?),
        "export_data" => encode(export_data(host::State(state), argument::<String>(&params, "kind")?).await?),
        "restore_data" => encode(restore_data(host::State(state), argument::<bool>(&params, "backup")?).await?),
        "delete_local_data" => encode(delete_local_data(host::State(state)).await?),
        "ui_event" => encode(actions::ui_event(host::State(state), argument::<String>(&params, "action")?, argument::<String>(&params, "target")?).await?),
        "open_log_folder" => encode(actions::open_log_folder(host::State(state)).await?),
        "start_mtu_tuning" => encode(actions::start_mtu_tuning(host::State(state),serde_json::from_value(params).map_err(|_| Error::new("InvalidArgument","mtu-tuning","Invalid MTU request"))?).await?),
        "start_mtu" => encode(actions::start_mtu(host::State(state), argument::<String>(&params, "target")?).await?),
        "start_best_server" => encode(actions::start_best_server(host::State(state), argument::<u8>(&params, "samples")?).await?),
        _ => Err(Error::new("UnknownCommand", "ipc", "Unsupported command")),
    }
}
